('role-inventory-clerk', 'inventory_clerk', 'Inventory Clerk', 'Access to item master, stock adjustments, inventory transfers, and inventory reports.', 'custom', NULL, 0, 1, '2026-07-30 14:15:24', '2026-07-30 14:15:24'),
('role-manager', 'manager', 'Manager', 'Access to day-to-day operations, sales, purchases, inventory, and operational reports.', 'custom', NULL, 1, 1, '2026-07-30 14:15:24', '2026-07-30 14:15:24'),
